def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Base thresholds more generous early, more demanding later
    if round_num <= 5:
        base_threshold = 0.2
    elif round_num <= 15:
        base_threshold = 0.4
    else:
        base_threshold = 0.6

    # Use own donation rate to adjust
    if len(my_history) >= 5:
        recent_own = my_history[-5:]
        own_donate_count = sum(1 for entry in recent_own if entry['action'])
        own_donate_rate = own_donate_count / 5.0
    else:
        own_donate_rate = 0.5  # neutral assumption early

    # Use received donations (partner_action) to adjust
    if len(my_history) >= 5:
        recent_own = my_history[-5:]
        received_donate_count = sum(1 for entry in recent_own if entry.get('partner_action'))
        received_rate = received_donate_count / 5.0
    else:
        received_rate = 0.5

    # If we have been generous and also well-treated, lower threshold (more forgiving)
    if own_donate_rate > 0.6 and received_rate > 0.6:
        threshold = base_threshold - 0.2
    elif own_donate_rate < 0.3 and received_rate < 0.3:
        # If both parties have been stingy, raise threshold
        threshold = base_threshold + 0.2
    else:
        threshold = base_threshold

    threshold = max(-1.0, min(1.0, threshold))
    return recipient_reputation > threshold
